package test;
import org.eclipse.core.runtime.preferences.BundleDefaultsScope;
import org.osgi.service.prefs.Preferences;

public class Example {
    public void method() {
        Preferences bundleDefaults = new BundleDefaultsScope().getNode("plugin.id");
    }
}

afterExample:
package test;
import org.eclipse.core.runtime.preferences.BundleDefaultsScope;
import org.osgi.service.prefs.Preferences;

public class Example {
    public void method() {
        Preferences bundleDefaults = BundleDefaultsScope.INSTANCE.getNode("plugin.id");
    }
}

